{{ config(materialized='table') }}

with
pit_legal_vehicle_legal_vehicle_detail_ranked as (
    select
        legal_vehicle_hk,
        effective_from,
        dense_rank() over (partition by legal_vehicle_hk order by hashdiff_basis_version desc) as dpf_version_rank
    from {{ ref("investment__legal_vehicle_vault__sat_legal_vehicle_detail") }}
),
pit_legal_vehicle_legal_vehicle_detail_scoped as (
    select
        legal_vehicle_hk,
        effective_from
    from pit_legal_vehicle_legal_vehicle_detail_ranked
    where dpf_version_rank = 1
),
pit_legal_vehicle_spine as (
    select distinct
        legal_vehicle_hk,
        effective_from as as_of
    from pit_legal_vehicle_legal_vehicle_detail_scoped
),
pit_legal_vehicle_legal_vehicle_detail as (
    select
        pit_legal_vehicle_spine.legal_vehicle_hk as legal_vehicle_hk,
        pit_legal_vehicle_spine.as_of as as_of,
        max(pit_legal_vehicle_legal_vehicle_detail_stored.effective_from) as legal_vehicle_detail_effective_from
    from pit_legal_vehicle_spine
    left join pit_legal_vehicle_legal_vehicle_detail_scoped as pit_legal_vehicle_legal_vehicle_detail_stored
        on pit_legal_vehicle_legal_vehicle_detail_stored.legal_vehicle_hk = pit_legal_vehicle_spine.legal_vehicle_hk
        and pit_legal_vehicle_legal_vehicle_detail_stored.effective_from <= pit_legal_vehicle_spine.as_of
    group by pit_legal_vehicle_spine.legal_vehicle_hk, pit_legal_vehicle_spine.as_of
),
pit_legal_vehicle_joined as (
    select
        pit_legal_vehicle_spine.legal_vehicle_hk as legal_vehicle_hk,
        pit_legal_vehicle_spine.as_of as as_of,
        pit_legal_vehicle_legal_vehicle_detail.legal_vehicle_detail_effective_from as legal_vehicle_detail_effective_from
    from pit_legal_vehicle_spine
    left join pit_legal_vehicle_legal_vehicle_detail
        on pit_legal_vehicle_legal_vehicle_detail.legal_vehicle_hk = pit_legal_vehicle_spine.legal_vehicle_hk and pit_legal_vehicle_legal_vehicle_detail.as_of = pit_legal_vehicle_spine.as_of
)

select
    cast(legal_vehicle_hk as {{ dpf_type('string') }}) as legal_vehicle_hk,
    cast(as_of as {{ dpf_type('date') }}) as as_of,
    cast(legal_vehicle_detail_effective_from as {{ dpf_type('date') }}) as legal_vehicle_detail_effective_from
from pit_legal_vehicle_joined
